  "ingestion_status": {
    "term_id": "ingestion_status",
    "display_name": "Ingestion Status",
    "category": "data_quality",
    "short_definition": "State of one data-ingestion run for a source.",
    "full_definition": "Each ingestion run moves through queued, running and one final state. succeeded: data stored. skipped: an identical run (same source, job, parameters and window) had already succeeded, so nothing was fetched again. failed: the attempt raised an error and may be retried. dead_lettered: every retry failed.",
    "formula": "enum: queued | running | succeeded | failed | dead_lettered | skipped",
    "unit": "label",
    "example": "Running the same SEC filing job twice records succeeded, then skipped.",
    "direction": "N/A",
    "interpretation": "skipped is healthy; dead_lettered needs attention.",
    "why_it_matters": "Shows whether the latest data actually arrived and whether a failure needs attention.",
    "source": "apps/api/src/autotrading/ingestion/runner.py",
    "source_url": "https://github.com/stevenyang0714/autotrading/blob/main/apps/api/src/autotrading/ingestion/runner.py",
    "as_of": "2026-10-05",
    "update_cadence": "per run",
    "caveats": "A failed run may still be retried; only dead_lettered is final.",
    "related_terms": [
      "data_freshness",
      "dead_letter"
    ],
    "methodology_version": "0.1.0"
  },
  "license_status": {
    "term_id": "license_status",
    "display_name": "License Status",
    "category": "provenance",
    "short_definition": "Whether we are permitted to store and display a source's data, and how.",
    "full_definition": "The usage rights attached to a source's data. public: public-domain or openly licensed data. licensed_personal: licensed for this single user's personal use, with no redistribution. licensed_redistribution: licensed for display to others. restricted: usable under provider terms with limits, for example some series carry third-party copyright. unknown: not yet reviewed.",
    "formula": "enum: public | licensed_personal | licensed_redistribution | restricted | unknown",
    "unit": "label",
    "example": "FRED is restricted because some series carry third-party copyright; SEC EDGAR is public.",
    "direction": "N/A",
    "interpretation": "Shows the usage rights attached to the data.",
    "why_it_matters": "Prevents unlicensed storage or display (ADR-001, no redistribution).",
    "source": "Build spec 02 §4 and §27.1; ADR-001; config/sources.yaml",
    "source_url": "https://github.com/stevenyang0714/autotrading/blob/main/config/sources.yaml",
    "as_of": "2026-10-05",
    "update_cadence": "per source configuration",
    "caveats": "Provider terms change; re-verify periodically and before paying for or enabling a source.",
    "related_terms": [
      "access_status",
      "source_tier"
    ],
    "methodology_version": "0.1.0"
  },
